VALUES (
    '019e4f1e-5b5e-789c-bf77-83f3f304e4ab',
    '019e4eb3-663b-769e-88b1-d2b5c7fb6d5c',
    '019e4eae-721e-7457-b6b1-297fa29634f0',
    NULL,
    'Tôi thấy bài viết này có vẻ hơi ''hiện đại hóa'' tư tưởng của vua Trần Thái Tông rồi. Làm sao chúng ta chắc chắn rằng vị vua thời đó thực sự dùng hình ảnh ''áo giáp vàng'' để so sánh với sự giác ngộ như cách người viết đang diễn giải? Cần có dẫn chứng từ Khóa Hư Lục hoặc các văn bản gốc tin cậy chứ không nên suy diễn tùy tiện như thế này.',
    '2025-10-31 09:51:34.000',
    '2025-10-31 12:49:34.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
