VALUES (
    '019e4f1e-6837-76cc-bd55-63c944645cd3',
    '019e4eb3-6643-7d9b-a059-747f44fa0313',
    '019e4eae-7219-797f-930d-dee6b3327aa1',
    NULL,
    'Tôi thấy tác giả đang suy diễn hơi quá về tư tưởng thời Trần. Các ghi chép về Thiền tông đời Trần chủ yếu mang tính chất chính trị hóa Phật giáo để phục vụ vương quyền. Liệu việc bám víu vào ngôn từ như tác giả nói có thực sự là vấn đề chính, hay bản chất các vị vua thời đó chỉ mượn danh Thiền để củng cố địa vị? Đề nghị tác giả dẫn chứng cụ thể từ ''Phổ thuyết hướng thượng nhất lộ'' thay vì nói chung chung.',
    '2026-06-18 16:52:18.000',
    '2026-06-19 00:01:18.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
