    NULL,
    'Tôi thấy bài viết có vẻ đang lý tưởng hóa cách giải quyết của vua Anh Tông. Liệu việc Chế Chí hàng phục có thật sự êm đẹp như sử chép hay còn những góc khuất chính trị nào mà chính sử thời sau đã lược bỏ để làm đẹp hình ảnh triều Trần? Các nguồn tư liệu ngoài Đại Việt Sử Ký Toàn Thư có ghi chép gì khác về sự kiện này không?',
    '2025-12-22 18:25:58.000',
    '2025-12-23 01:18:58.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
