VALUES (
    '019e4f27-9e36-7178-a611-ac10af0165a7',
    '019e4eba-e45f-7f99-b9f3-240ace6a9808',
    '019e4eae-71d9-7d2c-a73d-5cf4f8df974d',
    '019e4f27-9e35-7cbc-a959-4607d81af9e1',
    'Chào bạn, góc nhìn hoài nghi là rất cần thiết khi nghiên cứu sử. Tuy nhiên, việc Đoàn Nhữ Hài chiêu dụ thành công là chi tiết được ghi chép khá đồng nhất trong các bộ sử. Chúng ta nên đặt sự kiện này trong bối cảnh triều Trần đang chú trọng chiến lược ''tâm công'' để giảm thiểu hao tổn binh lực sau nhiều năm đánh Nguyên. Việc Chế Chí hàng phục không chỉ là may mắn mà là kết quả của sự chuẩn bị quân sự áp đảo khiến đối phương không còn lựa chọn nào khác.',
    '2026-01-22 18:29:35.000',
    '2026-01-23 03:17:35.000',
    NULL
);


INSERT INTO comments (
