VALUES (
    '019e4f2f-3b12-7663-88da-008e51f339c7',
    '019e4ec1-ff25-7ca5-b46f-360f59f652f2',
    '019e4eae-71d6-7792-aec4-6c40cfd028f4',
    '019e4f2f-3b11-7014-9e8d-d0f4c4ae2aee',
    'Góc nhìn của bạn rất đáng suy ngẫm. Tuy nhiên, sự chuyển dịch là có thật nếu nhìn vào các kỳ thi Thái học sinh từ thời Trần Thái Tông đến thời Trần Hiến Tông. Dù tôn thất nắm giữ quân đội và các vùng trọng yếu, nhưng ở bộ máy hành chính trung ương, các vị như Lê Quát hay Phạm Sư Mạnh đã thực sự nắm giữ những vị trí then chốt về tư pháp và giáo dục. Đây là sự chuyển đổi từ quản lý gia tộc sang quản lý hành chính chuyên nghiệp theo Nho giáo, không thể phủ nhận sự tiến bộ này.',
    '2026-07-14 06:10:35.000',
    '2026-07-15 05:13:35.000',
    NULL
);


INSERT INTO comments (
