    NULL,
    'Đọc bài viết mới thấy cha ông ta thời Trần không chỉ giỏi binh pháp mà tư duy kinh tế cũng rất cởi mở. Cảng Vân Đồn xưa chắc hẳn sầm uất lắm, tàu bè qua lại tấp nập không kém gì các thương cảng lớn trong khu vực thời bấy giờ.',
    '2026-06-19 09:19:42.000',
    '2026-06-20 02:29:42.000',
    NULL
);


INSERT INTO comments (
