)
VALUES (
    '019e4f39-814a-731c-b586-3737a0ee14f1',
    '019e4ec9-cda6-70c5-80b3-0e80fa34a566',
    '019e4eae-71d0-7f6a-aa43-53651a991342',
    NULL,
    'Bài viết phân tích khá tốt về Hào khí Đông A. Tuy nhiên, cần lưu ý rằng bên cạnh Hịch tướng sĩ, những bài thơ của các vị vua Trần như Trần Nhân Tông cũng đóng góp rất lớn vào việc xây dựng hệ tư tưởng Phật giáo hòa quyện với tinh thần yêu nước, tạo nên bản sắc độc đáo cho văn học thời kỳ này.',
    '2026-04-23 16:20:24.000',
    '2026-04-24 10:11:24.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
