VALUES (
    '019e4f39-8b0c-71f1-b5a6-4557e626f7a8',
    '019e4ec9-cdab-73b8-9749-5a0a25d484e2',
    '019e4eae-7221-7fdc-ba3d-b68aadb31db2',
    NULL,
    'Tôi thấy nhiều người cứ thần thánh hóa Hịch tướng sĩ. Liệu văn bản này có thực sự được viết nguyên văn bởi Trần Hưng Đạo hay chỉ là tác phẩm được các sử gia đời sau thêm thắt để củng cố tư tưởng trung quân ái quốc? Tôi nghi ngờ về tính xác thực của ngôn từ trong các bản dịch hiện nay.',
    '2026-07-25 00:29:47.000',
    '2026-07-25 16:29:47.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
