VALUES (
    '019e4f39-b865-7088-9623-a90e66fbcf2f',
    '019e4ec9-fc26-7f88-b2c1-f9bb45cbc6bf',
    '019e4eae-71d0-7f6a-aa43-53651a991342',
    NULL,
    'Bạch Đằng giang phú của Trương Hán Siêu không chỉ là một tác phẩm văn học thuần túy mà còn là minh chứng cho tư tưởng ''Hào khí Đông A'' thời Trần. Việc nhấn mạnh vào sự hòa hợp giữa vua tôi, đặc biệt là tinh thần đoàn kết tại hội nghị Diên Hồng, đã tạo nên sức mạnh tổng lực giúp Đại Việt đứng vững trước vó ngựa quân Nguyên.',
    '2026-08-07 23:07:34.000',
    '2026-08-08 15:24:34.000',
    NULL
);


INSERT INTO comments (
