VALUES (
    '019e4f3b-0f88-7dc6-8e69-9d69094a633f',
    '019e4eca-d516-7837-867a-34cbdae3f309',
    '019e4eae-71d2-7b79-b12a-03e3c7e17d17',
    '019e4f3b-0f87-7e76-b6b4-95de81e3d232',
    'Góc nhìn của bạn rất đáng lưu tâm. Tuy nhiên, nếu đối chiếu qua các di vật tại chùa Thái Lạc hay các bệ đá thời Trần, sự thay đổi hình khối là có cơ sở khảo cổ học rõ ràng. Nghệ nhân thời Trần chịu ảnh hưởng của tư tưởng Thiền tông mạnh mẽ hơn, dẫn đến nét chạm khỏe khoắn, thoát khỏi tính quy phạm khắt khe của thời Lý. Bạn có thể tham khảo thêm các công trình của các nhà nghiên cứu mỹ thuật cổ để thấy sự chuyển biến về tạo hình này.',
    '2026-09-07 01:19:56.000',
    '2026-09-07 19:05:56.000',
    NULL
);


INSERT INTO comments (
