    '019e4eca-fa10-740f-8ca7-20a0de2c55ae',
    '019e4eae-721e-7457-b6b1-297fa29634f0',
    NULL,
    'Tôi thấy bài viết có vẻ hơi quá lời về yếu tố dân gian trong nghệ thuật thời Trần. Thời đó tư tưởng Nho giáo và Phật giáo vẫn là chủ đạo, làm sao mà nghệ thuật lại có thể cởi mở và đậm chất dân gian như mô tả được? Liệu có bằng chứng khảo cổ nào thực sự chứng minh sự giao thoa này không, hay chỉ là suy diễn của người viết?',
    '2026-05-06 21:57:54.000',
    '2026-05-07 19:44:54.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
