VALUES (
    '019e4f3b-f18e-737f-b11f-21ec74af560e',
    '019e4ecb-6d23-7feb-87ad-c7f516030f2a',
    '019e4eae-71ed-7df9-99c9-91624f6bc58e',
    NULL,
    'Phân tích của bạn rất thú vị. Thực tế, khả năng cơ động của khinh kỵ binh Mông Cổ là một thử thách lớn, nhưng nhà Trần đã chuẩn bị rất kỹ qua các cuộc tập trận và chiến lược vườn không nhà trống. Quan trọng nhất là sự đoàn kết quân dân và việc tận dụng địa hình sông ngòi, nơi kỵ binh không thể phát huy tối đa sức mạnh. Chúng ta cần nhìn vào Hội nghị Diên Hồng để hiểu rõ hơn về sự thống nhất ý chí này.',
    '2026-01-30 23:37:21.000',
    '2026-01-31 21:23:21.000',
    NULL
);


INSERT INTO comments (
