VALUES (
    '019e4f3c-df63-715d-b922-51324a87fcd6',
    '019e4ecb-e397-7792-b2e9-dbc60c9c69d7',
    '019e4eae-71d4-7424-bc50-0e6ff1d623e1',
    '019e4f3c-df62-754d-9b7d-19470d3e5033',
    'Góc nhìn của bạn rất thú vị. Tuy nhiên, nếu đối chiếu với Nguyên sử, cụ thể là phần viết về cuộc viễn chinh của Ngột Lương Hợp Thai (Uriangkhađai), thì việc quân đội họ gặp khó khăn về lương thảo do chiến thuật thanh dã là có cơ sở. Sự kiện rút lui không chỉ là do quân ta phản công mà còn do áp lực về hậu cần tại vùng khí hậu nhiệt đới không thuận lợi cho kỵ binh Mông Cổ.',
    '2025-12-06 06:33:20.000',
    '2025-12-06 13:40:20.000',
    NULL
);


INSERT INTO comments (
    id,
