    '019e4ecd-2adb-72b3-9260-712d4056a4e1',
    '019e4eae-722a-7d88-a522-5ab60ce4ede1',
    NULL,
    'Bạn nhầm lẫn nghiêm trọng rồi. Thời nhà Lý làm gì có Thoát Hoan hay quân Nguyên? Thoát Hoan là tướng nhà Nguyên, đánh Đại Việt thời nhà Trần cơ mà. Có vẻ bạn đang trộn lẫn lịch sử thời Lý và thời Trần vào làm một rồi.',
    '2026-01-09 02:50:43.000',
    '2026-01-09 21:15:43.000',
    NULL
);


INSERT INTO comments (
