    '019e4f42-2cfb-7886-81fc-0658a081977d',
    '019e4ed0-8eae-7960-8eda-2039ee742e81',
    '019e4eae-71f0-7a7c-aebe-d78d942756ce',
    NULL,
    'Phân tích của bài viết rất đáng chú ý. Việc sử dụng tên thụy hiệu hay tên hiệu khác trong văn bản ngoại giao thời xưa là một chiến lược để tránh phạm húy hoặc bảo toàn sự tôn nghiêm của quân chủ. Về trường hợp Phạm Sư Mạnh, tôi cho rằng chúng ta cần đối chiếu kỹ hơn với ''Nguyên sử'' để xác định liệu các mốc thời gian có bị lệch do cách tính lịch pháp khác biệt giữa hai triều đại hay không.',
    '2026-05-23 19:35:29.000',
    '2026-05-24 02:59:29.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
