)
VALUES (
    '019e4f42-5b16-706f-a959-951672500815',
    '019e4ed0-b43d-7e85-8deb-61ae9c9f6ae2',
    '019e4eae-7225-7884-b4fd-2a6afb8a7b76',
    NULL,
    'Tôi thấy bài viết có vẻ đang cố gắng tô hồng cho chính sách ngoại giao thời cuối Trần. Thực tế lúc đó triều đình đã mục nát, việc triều cống liên tục cho nhà Minh chẳng qua là cách để giữ ghế thôi chứ làm gì có tính toán chiến lược cao siêu như tác giả nói. Bạn có dẫn chứng cụ thể nào cho thấy sự ''tinh tế'' trong việc thay đổi tên vua không?',
    '2026-07-02 11:22:39.000',
    '2026-07-03 01:21:39.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f42-5b17-7774-8b79-35744a4f98e9',
    '019e4ed0-b43d-7e85-8deb-61ae9c9f6ae2',
    '019e4eae-71ec-7341-a302-e66504f69a27',
    '019e4f42-5b16-706f-a959-951672500815',
    'Chào bạn, việc nhìn nhận ngoại giao cần tách bạch giữa tình thế nội bộ và áp lực từ đế chế phương Bắc. Việc nhà Minh quan tâm tới danh tính vua Đại Việt là để củng cố tính chính danh của họ trong quan hệ ngoại giao. Dẫn chứng về việc sứ thần phải trần tình về tên gọi Nhật Kiên hay Thúc Minh được ghi chép khá rõ trong Minh Thực Lục, cho thấy họ luôn giám sát chặt chẽ. Đây là sự ứng biến để tránh cái cớ can thiệp quân sự, chứ không chỉ là sự phục tùng đơn thuần.',
    '2026-04-20 18:52:24.000',
    '2026-04-21 15:23:24.000',
    NULL
);


INSERT INTO comments (
