VALUES (
    '019e4f46-f195-7274-9037-9807cb285677',
    '019e4ed3-2a7a-77bb-b12e-d40970e10c5f',
    '019e4eae-71ea-7435-8246-5d65a243d586',
    '019e4f46-f194-72e2-bbee-90a0c5640961',
    'Bạn đặt câu hỏi rất xác đáng. Thực tế, Đại Việt Sử ký toàn thư có ghi chép về việc Trần Lý khởi nghiệp từ nghề chài lưới, nhưng các nhà nghiên cứu hiện nay cho rằng họ Trần thực ra là một thế lực hào trưởng địa phương có thế lực kinh tế lớn ở vùng Lưu Gia, Thái Bình. Việc nhấn mạnh nghề đánh cá có thể là cách phản ánh sự gắn kết của họ với vùng đất này, chứ không hẳn là họ nghèo khó như cách chúng ta hiểu về ''nghề chài lưới'' thời nay.',
    '2025-11-26 04:16:52.000',
    '2025-11-27 01:27:52.000',
    NULL
);


INSERT INTO comments (
