VALUES (
    '019e4f47-01a4-7246-9789-b0bfe355ee9a',
    '019e4ed3-5b28-72b8-baac-fae1e4db3c65',
    '019e4eae-7227-7bac-be6c-7ed468a3634b',
    NULL,
    'Tôi thấy bài viết hơi lãng mạn hóa chế độ này. Thực tế thì việc nhường ngôi sớm đôi khi chỉ là để ép vua con vào khuôn khổ hoặc do nội bộ hoàng tộc tranh giành quyền lực chứ đâu phải lúc nào cũng vì sự ổn định đất nước. Có tài liệu nào chứng minh đây là cơ chế chủ động không hay chỉ là cách các Thượng hoàng giữ quyền kiểm soát?',
    '2026-04-10 05:11:38.000',
    '2026-04-10 21:38:38.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
