    '019e4eda-6c7b-7057-8625-e5eb2b371315',
    '019e4eae-7227-7bac-be6c-7ed468a3634b',
    NULL,
    'Tôi thấy tác giả đang suy diễn hơi quá về quyền sở hữu của công thần. Việc nhà vua cấp ruộng ''thác đao'' thời đó chủ yếu là ban quyền thu thuế, chứ đâu thể coi là tư hữu hoàn toàn được. Có tài liệu nào chứng minh rõ họ được quyền mua bán hay chuyển nhượng mảnh đất đó không, hay chỉ là được hưởng lợi tức từ dân đinh?',
    '2026-01-26 04:37:23.000',
    '2026-01-26 12:06:23.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
