    '019e4edb-5e3c-75bc-b0a9-3d1ec363b33b',
    '019e4eae-7216-7fc2-9d38-a8a11f2962dc',
    NULL,
    'Tôi không đồng ý với nhận định quân Mông Cổ chỉ phá hoại cơ sở hạ tầng mà không có mục đích kinh tế. Nếu họ không muốn chiếm đóng lâu dài để khai thác tài nguyên thì tại sao lại lập ra các cơ quan cai trị và bắt cống nạp? Có bằng chứng sử học cụ thể nào cho thấy họ chỉ phá hủy mà không thu lợi không?',
    '2026-04-11 11:38:15.000',
    '2026-04-11 20:03:15.000',
    NULL
);


INSERT INTO comments (
    id,
