VALUES (
    '019e4f4d-b9d1-7492-9708-32862c2c0ba4',
    '019e4edb-5e3c-75bc-b0a9-3d1ec363b33b',
    '019e4eae-71df-7a78-afdc-2976b44fc7df',
    '019e4f4d-b9d0-75c3-9fa0-eb083981692a',
    'Góc nhìn của bạn rất đáng suy ngẫm. Thực tế là mục tiêu của nhà Nguyên khi đánh Đại Việt là biến nước ta thành bàn đạp để đánh xuống phía Nam. Việc phá hoại đôi khi là đòn tâm lý chiến nhằm làm suy sụp ý chí kháng cự thay vì chỉ là mục đích kinh tế thuần túy. Chúng ta cần phân biệt rõ giữa giai đoạn chiếm đóng tạm thời và ý đồ thiết lập bộ máy hành chính lâu dài.',
    '2026-03-22 21:49:29.000',
    '2026-03-23 12:38:29.000',
    NULL
);


INSERT INTO comments (
