VALUES (
    '019e4f4e-0596-7c7e-ad26-0390b7fa2f15',
    '019e4edb-ab5e-7fd1-9ca9-ae6b9536ba2a',
    '019e4eae-71e9-7262-b21f-f080d0377e5f',
    '019e4f4e-0595-7950-944a-4f0c3a75f2fc',
    'Chào bạn, con số 70 vạn thạch xuất hiện trong các bộ chính sử như Đại Việt Sử Ký Toàn Thư. Dù ghi chép lịch sử có thể có tính chất biểu tượng, nhưng việc đoàn thuyền Trương Văn Hổ bị đánh tan tại Vân Đồn là sự kiện có thực, gây ảnh hưởng trực tiếp đến khả năng tiếp tế của Thoát Hoan. Việc mất đi nguồn lương chính này khiến quân Nguyên rơi vào cảnh ''đói khát'' là điều hoàn toàn hợp lý về mặt chiến thuật quân sự.',
    '2026-07-07 19:59:55.000',
    '2026-07-08 19:45:55.000',
    NULL
);


INSERT INTO comments (
