VALUES (
    '019e4f51-cd53-7d63-8fb1-175a8d9858be',
    '019e4ede-db33-79ec-8b05-da5ed8a163d3',
    '019e4eae-721a-7bae-b953-05be29912692',
    NULL,
    'Tôi thấy bài viết có vẻ hơi khiên cưỡng khi gắn liền sự thay đổi nét chạm khắc với các cuộc khởi nghĩa nông dân. Liệu có bằng chứng khảo cổ nào khẳng định trực tiếp mối liên hệ này hay chỉ là suy luận của người viết? Các công trình thời Trần trải dài khắp cả nước, tôi nghi ngờ về tính đồng nhất trong phong cách của các vùng miền thời bấy giờ.',
    '2026-06-26 22:23:35.000',
    '2026-06-27 08:37:35.000',
    NULL
);


INSERT INTO comments (
