VALUES (
    '019e4f51-f0cd-7d0e-803f-d49deab20520',
    '019e4ede-db3a-7c8e-b1c5-1f27f00c175e',
    '019e4eae-7219-797f-930d-dee6b3327aa1',
    NULL,
    'Tôi thấy tác giả hơi nặng lời khi đổ lỗi cho việc bảo tồn. Thời đó chiến tranh liên miên, giữ được đất nước đã khó, lấy đâu ra nhân lực mà xây nhà che bia như phương Bắc? Hơn nữa, ông có bằng chứng cụ thể nào cho thấy việc bia đá bị hư hỏng là do sự ''buông xuôi'' của triều đình thay vì tác động của thời gian và thiên tai không?',
    '2026-01-14 07:34:00.000',
    '2026-01-14 21:48:00.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f51-f0ce-7721-bc19-622d16edfc82',
    '019e4ede-db3a-7c8e-b1c5-1f27f00c175e',
    '019e4eae-71db-7af1-bfe1-b2249485ff0a',
    '019e4f51-f0cd-7d0e-803f-d49deab20520',
    'Góc nhìn của bạn rất đáng suy ngẫm. Thực tế, tư liệu về kỹ thuật khắc đá thời Trần cho thấy sự thay đổi rõ rệt từ thời Trần Dụ Tông trở về sau, phản ánh sự khủng hoảng kinh tế xã hội chứ không hoàn toàn do thiếu ý thức bảo tồn. Lê Quý Đôn trong ''Đại Việt thông sử'' cũng chỉ ghi chép theo quan điểm thời đại ông, chúng ta cần đặt trong bối cảnh ngân khố quốc gia lúc đó đang cạn kiệt vì binh đao để có cái nhìn công tâm hơn.',
    '2026-02-22 23:12:45.000',
    '2026-02-23 22:40:45.000',
    NULL
);


INSERT INTO comments (
