VALUES (
    '019e4f52-0e0a-728e-bcaf-c8d93b3ed9e5',
    '019e4edf-2ec6-7694-8917-f29e7b3f6536',
    '019e4eae-7216-7fc2-9d38-a8a11f2962dc',
    NULL,
    'Tôi thấy nghi ngờ về tính xác thực của những bức chân dung này. Thời ấy làm gì đã có kỹ thuật hội họa tả thực như bây giờ? Khả năng cao là các họa sĩ chỉ vẽ theo lối ước lệ, tập trung vào thần thái uy nghiêm để phục vụ mục đích tuyên truyền lòng trung thành của triều đình hơn là tái hiện diện mạo thật.',
    '2026-06-06 14:56:04.000',
    '2026-06-07 00:23:04.000',
    NULL
);


INSERT INTO comments (
