    '019e4ee0-5312-73a2-83b1-daaa58dfe338',
    '019e4eae-722e-799b-b91a-6c9e67908a78',
    NULL,
    'Chắc thời đó phát triển là nhờ nhà Trần có chính sách miễn thuế hoàn toàn cho nông dân trong suốt cả trăm năm phải không mọi người? Tôi nghe kể là dân không phải nộp tô thuế gì cả nên nhà nào cũng giàu có, buôn bán tấp nập lắm.',
    '2026-08-17 11:40:12.000',
    '2026-08-17 13:03:12.000',
    NULL
);


INSERT INTO comments (
