VALUES (
    '019e4f54-9672-78f1-bbad-ed0234e45217',
    '019e4ee0-5312-73a2-83b1-daaa58dfe338',
    '019e4eae-7218-7a02-bbdf-305d1f1c7b3c',
    NULL,
    'Tôi thấy bài viết hơi lý tưởng hóa thời Trần quá mức. Các bạn nói về sự cởi mở kinh tế nhưng thực tế việc kiểm soát ruộng đất của các vương hầu quý tộc thời đó cực kỳ chặt chẽ, tạo ra tầng lớp nô tỳ đông đảo. Liệu có bằng chứng nào xác thực về nền kinh tế hàng hóa phát triển rộng rãi không, hay chỉ là suy diễn dựa trên một vài ghi chép rời rạc trong Đại Việt Sử ký toàn thư?',
    '2026-07-04 00:23:30.000',
    '2026-07-04 17:14:30.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f54-9673-7506-9bc5-0a09aaed0d76',
    '019e4ee0-5312-73a2-83b1-daaa58dfe338',
    '019e4eae-71d7-752a-9af2-32b1a001f047',
    '019e4f54-9672-78f1-bbad-ed0234e45217',
    'Góc nhìn của bạn rất đáng lưu tâm. Tuy nhiên, khi phân tích tính chất xã hội thời Trần, chúng ta không thể bỏ qua các khảo cứu về hệ thống phủ, lộ và các thương cảng như Vân Đồn. Sự ''cởi mở'' ở đây được hiểu là tính linh hoạt trong phân cấp quản lý so với mô hình Nho giáo hóa cực đoan sau này. Việc tồn tại chế độ điền trang, thái ấp dù có tính chất sở hữu tập trung, nhưng lại là động lực để khai phá các vùng đất mới, thúc đẩy kinh tế nông nghiệp hàng hóa sơ khai vốn khác biệt hoàn toàn với tư duy trọng nông ức thương đời Lê sơ.',
    '2026-07-15 00:29:22.000',
    '2026-07-15 10:09:22.000',
    NULL
);


INSERT INTO comments (
