VALUES (
    '019e4f54-c81c-7927-9b39-ce4b545db3c8',
    '019e4ee0-c35c-7050-9a18-ec5fc3d725b6',
    '019e4eae-71e2-7f4e-a0f9-c08845a81638',
    '019e4f54-c81b-77b6-883d-817f63a34310',
    'Bạn đang nhầm lẫn khái niệm rồi. Chế độ nô tỳ thời Trần khác xa với chế độ nô lệ ở phương Tây. Gia nô thời này thường là những người tự nguyện bán thân để nương tựa vào các thế lực quý tộc hoặc là tù binh chiến tranh, nhưng họ vẫn có quyền lợi nhất định và được quản lý theo luật lệ cụ thể chứ không phải công cụ lao động bị tước đoạt nhân quyền hoàn toàn.',
    '2026-05-27 04:32:18.000',
    '2026-05-27 10:58:18.000',
    NULL
);


INSERT INTO comments (
