)
VALUES (
    '019e4f57-19e5-704f-b672-0ec52ea04894',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-71ee-7cb2-b296-83bb36bfea88',
    NULL,
    'Phân tích của chủ thớt khá thú vị, tuy nhiên cần lưu ý rằng chế độ sở hữu ruộng đất thời Trần không hoàn toàn là ''công hữu'' theo nghĩa hiện đại. Việc tồn tại các điền trang, thái ấp của vương hầu quý tộc cũng tạo ra những vùng lãnh địa bán độc lập, nơi người dân gắn bó mật thiết với chủ đất thay vì trực tiếp với triều đình.',
    '2026-06-02 04:30:11.000',
    '2026-06-02 23:41:11.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
