)
VALUES (
    '019e4f57-19e6-7d73-8eb5-78889924456a',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-721b-76eb-b045-f2c4681c6314',
    '019e4f57-19e5-704f-b672-0ec52ea04894',
    'Đúng là vậy, tôi thấy bài viết đang hơi lý tưởng hóa thời Trần. Nếu thực sự ruộng đất công hữu vững chắc thì tại sao các văn bia thời cuối Trần lại ghi nhận tình trạng lấn chiếm đất công của các thế lực quý tộc mạnh mẽ đến thế? Cần xem lại các nguồn sử liệu gốc thay vì chỉ nhìn vào các tổng kết mang tính lý thuyết.',
    '2026-06-08 03:56:13.000',
    '2026-06-08 05:50:13.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
