VALUES (
    '019e4f57-19e7-7aad-8602-6ed5e9463cd0',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-7204-77c8-8be0-7e812b0b9d83',
    NULL,
    'Đọc bài của bạn mà nhớ lại những câu chuyện bà ngoại kể về thời xưa, người dân dù nghèo nhưng làng xã gắn kết. Thời đó tinh thần đoàn kết từ làng lên nước chắc là nhờ hệ thống đê điều mà vua quan cùng chăm lo như tác giả nói, nghe thật ấm lòng.',
    '2026-04-21 22:07:16.000',
    '2026-04-22 15:00:16.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
