VALUES (
    '019e4f57-19e9-79f3-aca3-8db4a9cf07c5',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-71e6-7e46-8f59-a3ca647b9ebd',
    '019e4f57-19e8-7978-a088-48b5bdd334c7',
    'Bạn nhầm rồi, triều Trần vẫn có hệ thống thuế rất nghiêm ngặt, bao gồm cả thuế thân và thuế ruộng đất. Tuy nhiên, mức thuế thời đó được đánh giá là vừa phải, đủ để nuôi bộ máy và quân đội mà không làm kiệt quệ dân chúng, chính điều đó mới tạo ra sự ổn định.',
    '2026-04-26 00:14:19.000',
    '2026-04-26 11:10:19.000',
    NULL
);


INSERT INTO comments (
