VALUES (
    '019e4f57-19ea-7df6-88f9-3af7d3fe7edf',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-7217-7106-9ea1-ab200e2c6ec2',
    NULL,
    'Tôi vẫn hoài nghi về nhận định ''thiếu vắng sự cách biệt đẳng cấp''. Việc phân chia tôn thất và quý tộc với tầng lớp nô tỳ, dân thường thời Trần là rất rõ nét. Liệu sự ổn định đó có phải chỉ là bề nổi của một trật tự xã hội nghiêm ngặt?',
    '2026-03-07 05:51:17.000',
    '2026-03-08 02:00:17.000',
    NULL
);


INSERT INTO comments (
