VALUES (
    '019e4f57-19eb-7bd1-adaf-1d6ba7299316',
    '019e4ee2-6cc7-77ea-9bf8-28ce8fdbe132',
    '019e4eae-71f9-700d-88d9-5de301a01b9f',
    '019e4f57-19ea-7df6-88f9-3af7d3fe7edf',
    'Thực ra sự cách biệt là có, nhưng có lẽ nó không đè nặng lên đời sống tâm hồn của người dân như các giai đoạn Nho giáo hóa cực đoan sau này. Tinh thần Phật giáo phổ biến thời Trần giúp cho mối quan hệ giữa các tầng lớp bớt đi phần nào sự khắc nghiệt.',
    '2026-03-26 16:08:35.000',
    '2026-03-27 04:38:35.000',
    NULL
);


INSERT INTO comments (
