VALUES (
    '019e4f57-d0f9-79be-a592-5ae2b8c675b8',
    '019e4ee3-5956-75a9-a9cb-d7c7bd183bb7',
    '019e4eae-71d4-7424-bc50-0e6ff1d623e1',
    '019e4f57-d0f8-77f8-8ce5-cbfeb09ea4a1',
    'Góc nhìn của bạn rất thú vị. Thực tế, Đại Việt Sử ký toàn thư đã ghi chép khá cụ thể về sự mất kiểm soát của triều đình đối với các lộ phủ. Việc nhà Lý không thể dẹp loạn ở Hồng Châu hay Quốc Oai không chỉ là tranh chấp cục bộ, mà nó phản ánh sự suy giảm năng lực điều hành thực tế của trung ương. Dĩ nhiên, ý định ''lật đổ'' có thể chưa rõ ràng, nhưng sự bất ổn kéo dài là chất xúc tác không thể chối cãi cho sự chuyển giao quyền lực sau này.',
    '2026-05-25 22:07:56.000',
    '2026-05-26 05:25:56.000',
    NULL
);


INSERT INTO comments (
