    NULL,
    'Đọc lại lịch sử về Đỗ Khắc Chung mà vẫn thấy nổi da gà. Bản lĩnh của người xưa thật đáng nể, đối diện với tướng giặc mà vẫn giữ vững khí tiết. Thế hệ trẻ chúng ta cần học hỏi nhiều từ lòng tự tôn dân tộc này.',
    '2026-01-19 00:48:34.000',
    '2026-01-19 11:27:34.000',
    NULL
);


INSERT INTO comments (
