    '019e4eec-46db-78ce-baf4-c9c152356844',
    '019e4eae-71da-7553-9436-32c988b9def4',
    '019e4f60-a527-7ea3-bec0-6f76db2e12e0',
    'Bạn nói đúng là sử liệu luôn có tính chọn lọc, nhưng trong Đại Việt Sử Ký Toàn Thư, các sự kiện ngoại giao của Đỗ Khắc Chung được ghi lại khá nhất quán. Việc phân tích không nên chỉ nhìn vào lời thoại, mà nên nhìn vào bối cảnh chiến lược của nhà Trần thời điểm đó để thấy đây là những bước đi ngoại giao khôn khéo nhằm câu giờ.',
    '2025-10-08 10:29:15.000',
    '2025-10-08 11:26:15.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
