)
VALUES (
    '019e4f60-b5e7-7643-a0e3-84cbccca223a',
    '019e4eec-46e0-77fd-8262-4570fa02e25d',
    '019e4eae-7228-7ff6-8260-14f843b426b5',
    NULL,
    'Tôi thấy bài viết có vẻ đang lý tưởng hóa các quyết định của nhà Trần. Việc cử sứ sang nhà Nguyên thực sự là kế hoãn binh hay chỉ là sự bối rối khi đối mặt với quân Nguyên hùng mạnh? Sử sách đời sau biên soạn có thể đã tô vẽ thêm cho những nước đi này để hợp thức hóa chính thống, tôi nghi ngờ tính xác thực của việc ''vừa đánh vừa đàm'' này.',
    '2026-07-15 13:40:16.000',
    '2026-07-15 21:54:16.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
