VALUES (
    '019e4f60-b5e8-7d42-b480-5037d36484f0',
    '019e4eec-46e0-77fd-8262-4570fa02e25d',
    '019e4eae-71e4-728b-80fc-9943d8b4d98d',
    '019e4f60-b5e7-7643-a0e3-84cbccca223a',
    'Bạn cần xem xét bối cảnh trong Đại Việt sử ký toàn thư và cả Nguyên sử. Việc sử dụng ngoại giao không có nghĩa là không chuẩn bị quân sự. Việc điều động quân đội về các cửa ải trọng yếu diễn ra đồng thời với các hoạt động sứ bộ. Các ghi chép không chỉ là tô vẽ mà là sự phản ánh tư duy chiến lược ''dĩ bất biến ứng vạn biến'' của các tướng lĩnh thời bấy giờ nhằm tối ưu hóa nguồn lực hạn hẹp trước đế quốc Nguyên.',
    '2026-08-16 10:14:33.000',
    '2026-08-17 03:28:33.000',
    NULL
);


INSERT INTO comments (
