)
VALUES (
    '019e4f73-d064-7b9e-a16d-35397aa6ea32',
    '019e4f00-ffbc-7a51-a916-ebb8cef5bf48',
    '019e4eae-721a-7bae-b953-05be29912692',
    NULL,
    'Tôi thấy bài viết này đánh trúng vấn đề. Chúng ta hay lãng mạn hóa tư tưởng của quý tộc Trần. Liệu cái gọi là ''cư trần lạc đạo'' có thực sự là tư tưởng phổ quát hay chỉ là cách họ bao biện cho lối sống xa rời thực tế khi vương triều đã ổn định? Rất nghi ngờ về việc tầng lớp dân đen thời đó có tâm thế ''tùy duyên'' như vậy.',
    '2026-07-27 16:58:21.000',
    '2026-07-28 02:38:21.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f73-d065-7617-8d87-173e38a7eb20',
    '019e4f00-ffbc-7a51-a916-ebb8cef5bf48',
    '019e4eae-71d9-7d2c-a73d-5cf4f8df974d',
    '019e4f73-d064-7b9e-a16d-35397aa6ea32',
    'Bạn cần tách biệt tư tưởng triết học và điều kiện kinh tế xã hội. ''Cư trần lạc đạo'' của Điều Ngự Giác Hoàng là sự đúc kết từ thiền tông, nhấn mạnh vào nội tại thay vì phủ nhận thực tại. Việc áp dụng tư tưởng này cho bình dân là khiên cưỡng, vì người dân lao động cần những hình thái tín ngưỡng dân gian để tồn tại. Đây không phải là sự bao biện mà là sự phân tầng trong nhận thức luận thời Trần.',
    '2026-04-08 14:00:40.000',
    '2026-04-09 10:26:40.000',
    NULL
);


INSERT INTO comments (
