    '019e4eae-71e1-7d0c-84d3-e24faba96c12',
    '019e4f7b-13f7-7d2a-8e08-59797a524368',
    'Bạn đang nhầm lẫn một chút. Triều Trần nổi tiếng với tinh thần ''Sát Thát'' và chưa từng đầu hàng chính thức trước quân Nguyên. Việc cử sứ giả sang trại địch chỉ là sách lược hoãn binh để củng cố lực lượng, hoàn toàn khác với việc đầu hàng hay quỳ lạy.',
    '2026-07-21 06:36:43.000',
    '2026-07-21 10:48:43.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
