VALUES (
    '019e4f7b-3a85-708b-ba65-59756079ab8f',
    '019e4f08-7087-77fb-8a66-377fbe26c956',
    '019e4eae-71fb-7521-ae78-322c73f35ced',
    NULL,
    'Đọc bài viết mà thấy nổi da gà. Tinh thần Sát Thát không chỉ là lịch sử, nó là linh hồn của dân tộc mình. Thế hệ trẻ chúng ta cần phải ghi nhớ mãi những hy sinh của ông cha ngày trước.',
    '2026-04-01 07:35:13.000',
    '2026-04-01 21:45:13.000',
    NULL
);


INSERT INTO comments (
