VALUES (
    '019e4f7b-3a86-70dc-b759-7ecafebb3900',
    '019e4f08-7087-77fb-8a66-377fbe26c956',
    '019e4eae-721a-7bae-b953-05be29912692',
    '019e4f7b-3a85-708b-ba65-59756079ab8f',
    'Tôi thì thấy hơi hoài nghi về việc tất cả quân lính đều thích chữ. Liệu có phải chỉ là cách người đời sau thi vị hóa lòng yêu nước không? Có nguồn sử liệu chính thống nào khẳng định 100% quân sĩ đều làm vậy không?',
    '2025-12-23 05:17:03.000',
    '2025-12-23 12:56:03.000',
    NULL
);


INSERT INTO comments (
    id,
