    '019e4f08-7087-77fb-8a66-377fbe26c956',
    '019e4eae-720c-7464-b6c1-7dcc80923643',
    '019e4f7b-3a88-7807-9502-ff8b25209ac4',
    'Không hẳn là như vậy đâu bạn ơi. Đó là lời thề tự nguyện của quân dân, thể hiện quyết tâm đánh giặc thôi chứ không phải hình phạt bắt buộc đâu nhé. Nhưng đúng là hào khí thời đó cực kỳ mãnh liệt.',
    '2026-02-16 16:29:36.000',
    '2026-02-17 00:11:36.000',
    NULL
);


INSERT INTO comments (
    id,
