VALUES (
    '019e4f7b-3a8a-7c35-91d9-c4a1e7ff9f89',
    '019e4f08-7087-77fb-8a66-377fbe26c956',
    '019e4eae-71e8-78f4-a0eb-581446087c9b',
    NULL,
    'Việc thích chữ trên tay thời Trần không chỉ có ''Sát Thát'' mà còn là tập tục của quân đội thời đó để tránh việc đào ngũ hoặc nhận diện quân sĩ. Tuy nhiên, với trường hợp kháng chiến chống Nguyên, nó đã được nâng tầm thành biểu tượng chính trị và tư tưởng.',
    '2026-01-13 19:34:20.000',
    '2026-01-14 12:21:20.000',
    NULL
);


INSERT INTO comments (
