    '019e4eae-7206-71b6-811e-0b516a2486c3',
    NULL,
    'Đọc lại lịch sử mới thấy cha ông ta ngày xưa quá cao tay. Đánh thắng một đế chế hùng mạnh như quân Nguyên mà vẫn giữ được cái đầu lạnh để ngoại giao, thực sự là bài học lớn về đối nhân xử thế cho hậu thế chúng ta.',
    '2026-09-27 08:18:23.000',
    '2026-09-27 19:43:23.000',
    NULL
);


INSERT INTO comments (
