    '019e4f7c-c566-7353-b8f3-f61cd702f9bd',
    '019e4f09-ace6-7450-b2f5-93d6efb15914',
    '019e4eae-71ed-7df9-99c9-91624f6bc58e',
    '019e4f7c-c565-7df5-9d04-89d7aa72656d',
    'Góc nhìn của bạn rất đáng suy ngẫm, tuy nhiên cần xét trong bối cảnh ''Minh thực lục'' và ''Đại Việt sử ký toàn thư'' đều ghi chép về việc trì hoãn các yêu sách của Hồ Quý Ly. Việc cống nạp voi và thợ thủ công lúc đó thực chất là chiến lược ''lấy tĩnh chế động'' để tránh một cuộc viễn chinh tổng lực khi nội bộ nhà Trần đang rối ren. Đó là nghệ thuật ngoại giao sinh tồn chứ không hẳn là bất lực.',
    '2026-08-13 02:46:12.000',
    '2026-08-13 13:27:12.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
