)
VALUES (
    '019e4f7c-fdfa-752f-8d0c-57622ac79644',
    '019e4f09-aceb-78bd-9c59-95f4ec666deb',
    '019e4eae-71e9-7262-b21f-f080d0377e5f',
    NULL,
    'Phân tích của bạn rất xác đáng. Việc nhà Minh yêu cầu các sản vật lạ không chỉ là áp lực kinh tế mà còn là phép thử về sự phục tùng của triều đình Trần. Cần lưu ý rằng các ghi chép trong Minh thực lục đôi khi mang tính chất tô vẽ cho vị thế ''thiên triều'', nên việc đối chiếu với Đại Việt sử ký toàn thư là bắt buộc để có cái nhìn khách quan nhất.',
    '2026-04-07 15:54:29.000',
    '2026-04-07 17:45:29.000',
    NULL
);


INSERT INTO comments (
    id,
