VALUES (
    '019e4f7d-23e5-7927-bee5-8a5fdc1a16ae',
    '019e4f09-e6f4-7429-88c0-89188b2f1cdb',
    '019e4eae-71fe-7581-8d57-54934d5db3e1',
    NULL,
    'Đọc bài viết mà thấy tự hào quá. Ông cha ta thời đó thực sự rất cao tay khi biết tận dụng tình hình khu vực để giữ vững biên cương. Tinh thần của vua Chiêm cũng rất đáng nể, không phải ai cũng dám đối đầu với đế chế Nguyên hùng mạnh.',
    '2026-03-05 21:48:19.000',
    '2026-03-06 01:30:19.000',
    NULL
);


INSERT INTO comments (
