VALUES (
    '019e4f80-e674-792c-b30d-7f29d7d9e2fb',
    '019e4f0d-c782-7b51-8dea-ed978730a8ac',
    '019e4eae-7227-7bac-be6c-7ed468a3634b',
    NULL,
    'Tôi thấy tác giả có phần lý tưởng hóa quá mức sự chuyển dịch Nho giáo thời Trần. Việc các nhà Nho như Chu Văn An dần chiếm thế thượng phong không hẳn là sự ''thích nghi'' chủ động mà có vẻ giống sự suy thoái dần của Phật giáo sau thời vua Nhân Tông thì đúng hơn. Tác giả có dẫn chứng cụ thể nào cho thấy đây là kế hoạch có tính toán không?',
    '2026-03-24 11:36:32.000',
    '2026-03-25 09:13:32.000',
    NULL
);


INSERT INTO comments (
