    '019e4f12-f976-7992-b0a6-49dba3baf1e8',
    '019e4eae-7226-7936-a82d-a73f55a768b8',
    '019e4f85-f63d-713d-b25e-4906eb69ad0f',
    'Tôi không hoàn toàn đồng ý. Làm sao bạn phân biệt rạch ròi được giữa ''thực ấp'' và ''điền trang'' khi mà phần lớn sử liệu chúng ta có đều là biên chép lại từ thời sau? Có khi nào đây chỉ là cách gọi khác nhau của cùng một mô hình kinh tế không?',
    '2026-08-08 23:06:54.000',
    '2026-08-09 09:47:54.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
