VALUES (
    '019e4f86-c13b-73fb-8e2d-6d38a94050dc',
    '019e4f13-c3c0-7111-b7b7-4d9c5ea84c4a',
    '019e4eae-71d9-7d2c-a73d-5cf4f8df974d',
    '019e4f86-c13a-7a63-9537-a17acd75815b',
    'Chào bạn, thắc mắc của bạn rất hay. Trong Quốc triều hình luật (dù là thời Lê nhưng kế thừa nhiều từ thời Trần), đã có các quy định chặt chẽ về ruộng công và ruộng thờ cúng. Ở thời Trần, các văn bia như tại chùa Thánh Quang hay các bia ký liên quan đến điền trang thái ấp thường phản ánh thực tế là triều đình cấp sắc lệnh bảo hộ đất hương hỏa như một hình thức tư hữu hóa có kiểm soát để đảm bảo quyền lực quý tộc.',
    '2025-12-27 04:22:39.000',
    '2025-12-28 03:06:39.000',
    NULL
);


