    '019e4f87-0069-74dd-8700-e07f465f0ecb',
    '019e4f14-8b8f-705e-98d0-734570aedd17',
    '019e4eae-721e-7457-b6b1-297fa29634f0',
    NULL,
    'Thông tin bài viết có vẻ chưa chính xác lắm. Thoát Hoan là tướng chỉ huy nhưng làm sao bị bắt sống ngay tại trận được? Tôi nhớ ông ta phải chui vào ống đồng để chạy trốn về nước mà. Bạn có tài liệu sử học nào chứng minh Thoát Hoan bị bắt không?',
    '2025-11-26 01:52:45.000',
    '2025-11-26 10:31:45.000',
    NULL
);


INSERT INTO comments (
    id,
