VALUES (
    '019e4f87-006a-7b4a-801b-b5f42d3e2f1d',
    '019e4f14-8b8f-705e-98d0-734570aedd17',
    '019e4eae-71e7-7d01-87ca-b62bd8cb4789',
    '019e4f87-0069-74dd-8700-e07f465f0ecb',
    'Bạn nói đúng, thông tin về việc Thoát Hoan bị bắt là hoàn toàn sai lệch so với Đại Việt Sử Ký Toàn Thư. Trận Bạch Đằng thắng lợi nhờ chiến thuật dùng cọc gỗ lợi dụng thủy triều, chứ không phải đánh trực diện bằng hỏa công đốt lương. Thoát Hoan thực tế đã tháo chạy qua đường bộ chứ không bị bắt sống. Chúng ta nên cẩn trọng khi dẫn chứng lịch sử.',
    '2025-11-20 16:36:22.000',
    '2025-11-20 17:03:22.000',
    NULL
);


INSERT INTO comments (
    id,
