VALUES (
    '019e4f88-1381-7a5e-92be-0b0ed5aeab26',
    '019e4f15-af67-712f-8368-c218205e20f5',
    '019e4eae-721a-7bae-b953-05be29912692',
    NULL,
    'Tôi thấy bài viết có vẻ đang lý tưởng hóa cách dùng người thời Trần quá mức. Việc trọng dụng người tài không xuất thân quý tộc liệu có phổ biến thật không hay chỉ là vài trường hợp cá biệt được sử sách tô vẽ lại? Tôi nghi ngờ về tính chính xác của các ghi chép này khi mà giai cấp quý tộc họ Trần vẫn nắm giữ quyền lực tuyệt đối.',
    '2026-05-28 23:48:27.000',
    '2026-05-29 14:32:27.000',
    NULL
);


INSERT INTO comments (
    id,
