VALUES (
    '019e4f8b-e301-724e-8f3b-b029c7290fb1',
    '019e4f19-c2f8-7bf6-96a4-6d3339e6fcfd',
    '019e4eae-71f5-75ef-aa50-8c0e17daec19',
    '019e4f8b-e300-7971-849c-a2614d5fbc2f',
    'Góc nhìn của bạn rất đáng suy ngẫm. Tuy nhiên, sự khác biệt giữa Tức Mặc và Đông Triều có thể không phải là mâu thuẫn mà là các giai đoạn di cư của dòng họ này. Khi đối chiếu với các tư liệu điền dã và văn bia tại địa phương, chúng ta thấy được sự liên kết vùng miền rất rõ ràng. Việc nghiên cứu lịch sử cần kết hợp cả văn bản và khảo cổ thay vì chỉ dựa vào một bộ chính sử.',
    '2026-07-30 09:49:50.000',
    '2026-07-30 16:38:50.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8b-f8a3-7a5a-a506-3a4005df31b3',
    '019e4f19-c2fc-71eb-b6b3-52f7d7619cd9',
    '019e4eae-721e-7457-b6b1-297fa29634f0',
    NULL,
    'Tôi thấy việc cố gắng tách bạch giữa huyền thoại và thực tế trong gia phả nhà Trần rất mong manh. Làm sao ta biết được tài liệu nào là nguyên bản, tài liệu nào là sản phẩm của việc ''tô vẽ'' sau này? Nếu không có bằng chứng khảo cổ hay văn bia đương thời, thì mọi lập luận về nguồn gốc dân chài cũng chỉ là giả thuyết dựa trên các ghi chép đời sau vốn đã bị nhuốm màu tư tưởng.',
    '2026-08-20 17:49:53.000',
    '2026-08-21 08:45:53.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8b-f8a4-7fc1-8ef5-71d406d4abb2',
    '019e4f19-c2fc-71eb-b6b3-52f7d7619cd9',
    '019e4eae-71e2-7f4e-a0f9-c08845a81638',
    '019e4f8b-f8a3-7a5a-a506-3a4005df31b3',
    'Góc nhìn của bạn rất thực tế. Trong nghiên cứu sử học, chúng ta không coi gia phả là nguồn sử liệu sơ cấp tuyệt đối mà phải đối chiếu với ''Đại Việt sử ký toàn thư'' hoặc các văn bia thời Trần. Việc nhà Trần có gốc gác vùng sông nước vốn đã được các học giả như Trần Quốc Vượng phân tích qua tính cách phóng khoáng và nghệ thuật quân sự đặc thù. Việc phân loại dữ liệu cần kết hợp liên ngành, không nên bác bỏ hoàn toàn mà cần lọc bỏ những lớp ''huyền thoại hóa'' để thấy cái lõi lịch sử.',
    '2026-06-30 04:01:56.000',
    '2026-06-30 10:53:56.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-0851-7a4a-b138-96cda99dd1f9',
    '019e4f1a-0d2b-7e5a-a80b-d9899dbcf804',
    '019e4eae-7223-78d4-8a08-a8150f6b17bb',
    NULL,
    'Tôi thấy bài viết hơi cảm tính. Dù nhà Trần có gốc chài lưới, nhưng các bộ chính sử như Đại Việt Sử Ký Toàn Thư đều ghi rõ tổ tiên nhà Trần vốn ở hương Tức Mặc, phủ Thiên Trường. Việc bác bỏ ranh giới hành chính là một cách nhìn khá mơ hồ. Bạn có tài liệu hay nghiên cứu nào chứng minh giả thuyết về sự dịch chuyển từ Đông Triều đến tận vùng sông Hồng không, hay chỉ là suy đoán cá nhân?',
    '2026-07-16 23:53:06.000',
    '2026-07-17 06:26:06.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-2700-7f96-a16c-09d36a831734',
    '019e4f1a-0d30-7b53-9ef4-fdbf8579e594',
    '019e4eae-7228-7ff6-8260-14f843b426b5',
    NULL,
    'Tôi thấy bài viết hơi tô hồng quá mức về tính tự quản của làng xã thời Trần. Làm sao có thể khẳng định bộ máy trung ương thời đó thực sự hài hòa với làng xã khi mà chính sách điền trang thái ấp của các quý tộc nhà Trần thường xuyên gây áp lực lên quyền lợi của nông dân tự do? Cần dẫn chứng cụ thể hơn về sự vận hành thực tế này thay vì chỉ lý thuyết.',
    '2026-01-22 21:39:20.000',
    '2026-01-23 19:07:20.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-2701-78c6-94ed-7ef84c11f853',
    '019e4f1a-0d30-7b53-9ef4-fdbf8579e594',
    '019e4eae-71d6-7792-aec4-6c40cfd028f4',
    '019e4f8c-2700-7f96-a16c-09d36a831734',
    'Góc nhìn của bạn rất đáng lưu tâm. Đúng là chế độ điền trang thái ấp đã tạo ra những vùng đất thuộc quyền quản lý riêng của quý tộc, nhưng xét về tổng thể, chính quyền vẫn duy trì các đơn vị hành chính xã/làng với hội đồng bô lão có vai trò tự quản nhất định. Các sử liệu như Đại Việt Sử ký toàn thư có ghi chép về việc triều đình vẫn thu thuế và huy động quân dịch từ các đơn vị này, chứng tỏ mối liên kết hành chính vẫn bao trùm lên các thái ấp.',
    '2026-02-26 17:15:18.000',
    '2026-02-26 18:23:18.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-341a-7705-a877-994b1808f9fd',
    '019e4f1a-5226-75be-b111-5fe7f85fb1ed',
    '019e4eae-7216-7fc2-9d38-a8a11f2962dc',
    NULL,
    'Tôi thấy bài viết hơi lý tưởng hóa quá mức. Thực tế thời Trần đâu phải lúc nào cũng ''cha mẹ của dân'', các cuộc tranh giành quyền lực trong nội bộ hoàng tộc cũng đẫm máu không kém các triều đại khác. Việc phong thánh hóa nhà vua có thật sự hiệu quả hay chỉ là công cụ để củng cố quyền lực tập trung?',
    '2025-10-16 12:50:02.000',
    '2025-10-17 02:45:02.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-5ae6-7e77-89c7-ce4d3f8bbe81',
    '019e4f1a-522b-7eae-bc16-827bb63efab2',
    '019e4eae-7209-7602-9a34-173e30dedcab',
    NULL,
    'Đọc bài viết này mà thấy tự hào quá. Những vị vua nhà Trần thật sự có tâm và có tầm. Chính nhờ sự gắn kết như cha con giữa vua và dân mà quân dân ta mới đồng lòng ba lần đánh bại quân Nguyên Mông đầy kiêu ngạo.',
    '2026-05-10 10:44:01.000',
    '2026-05-10 22:21:01.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
    updated_at,
    deleted_at
)
VALUES (
    '019e4f8c-5ae7-7ad9-af40-2b9ae410f31f',
    '019e4f1a-522b-7eae-bc16-827bb63efab2',
    '019e4eae-721b-76eb-b045-f2c4681c6314',
    '019e4f8c-5ae6-7e77-89c7-ce4d3f8bbe81',
    'Tôi thấy tác giả đang hơi lý tưởng hóa vấn đề rồi. Thời nào chẳng có quan tham, dân khổ? Liệu tư tưởng ''cha mẹ của dân'' có thực sự phổ quát hay chỉ là cách quảng bá hình ảnh để giữ vững ngai vàng? Bạn có dẫn chứng cụ thể nào trong chính sử không?',
    '2026-08-07 00:44:49.000',
    '2026-08-07 17:40:49.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
