)
VALUES (
    '019e4f8c-5ae8-77a4-9cf3-427c1a8bc50a',
    '019e4f1a-522b-7eae-bc16-827bb63efab2',
    '019e4eae-71dc-759c-9320-5fdfc6e2a4e8',
    '019e4f8c-5ae7-7ad9-af40-2b9ae410f31f',
    'Góc nhìn của bạn rất thực tế. Tuy nhiên, trong ''Đại Việt Sử Ký Toàn Thư'', có những đoạn ghi chép vua Trần Thái Tông đích thân xuống đồng cày ruộng hay Trần Nhân Tông đi khất thực để gần dân. Đó là minh chứng cho sự chuyển hóa tư tưởng thành thực tiễn cai trị. Dù không thể phủ nhận yếu tố chính trị, nhưng sự dung hòa Phật giáo giúp nhà Trần tạo được lòng tin thực sự từ cộng đồng làng xã lúc bấy giờ.',
    '2026-06-05 18:17:16.000',
    '2026-06-06 13:45:16.000',
    NULL
);


INSERT INTO comments (
    id,
    post_id,
    author_id,
    parent_id,
    content,
    created_at,
