    deleted_at
)
VALUES (
    '019e4f8c-68a8-768b-812b-115c82727c41',
    '019e4f1a-7563-7772-996a-4d82ef85cf29',
    '019e4eae-71f0-7a7c-aebe-d78d942756ce',
    NULL,
    'Bài viết phân tích khá sâu sắc về tư tưởng ''lấy dân làm gốc'' của nhà Trần. Tuy nhiên, cần lưu ý thêm rằng việc vua Trần xuống đồng cày tịch điền không chỉ đơn thuần là nghi lễ, mà còn là sự khẳng định vị thế của hoàng đế trong hệ thống kinh tế nông nghiệp chủ đạo thời bấy giờ, nơi quyền sở hữu ruộng đất nhà nước được củng cố chặt chẽ.',
    '2026-06-26 14:10:58.000',
    '2026-06-27 02:20:58.000',
    NULL
);


INSERT INTO comments (
